pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        vm.assume(c.DEPOSITOR_ACCOUNT() != address(0));
        // Simulate two sequential calls to observe ordering
        // First call: set all values normally
        vm.prank(c.DEPOSITOR_ACCOUNT());
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        bytes32 hashAfterFirst = c.hash();
        bytes32 batcherHashAfterFirst = c.batcherHash();
        // Second call: swap the two parameters to see if the order of assignment matters
        vm.prank(c.DEPOSITOR_ACCOUNT());
        c.setL1BlockValues(_number, _timestamp, _basefee, _batcherHash, _sequenceNumber, _hash, _l1FeeOverhead, _l1FeeScalar);
        // If hash is set before batcherHash, the final values will be (_batcherHash, _hash) because
        // the second call sets hash=_batcherHash first, then batcherHash=_hash, so the last write to hash is from the first call? 
        // Actually simpler: the property is that after the first call, hash == _hash and batcherHash == _batcherHash.
        // That is the general rule.
        assertTrue(hashAfterFirst == _hash && batcherHashAfterFirst == _batcherHash);
    }
}

