pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        address caller
    ) public {
        vm.assume(caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);

        // Record the initial state
        uint64 initialNumber = c.number();

        // Attempt to call setL1BlockValues from a non-depositor
        vm.prank(caller);
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // After the call, state should remain unchanged (revert expected in reference)
        assertTrue(c.number() == initialNumber, "State changed despite non-depositor caller");
    }
}

